func TestImport_NestedMetadataAndNamespace(t *testing.T) {
	tests := []struct {
		name     string
		encoding Encoding
		input    string
	}{
		{
			name:     "YAML",
			encoding: EncodingYAML,
			input: `namespace:
  key: production
  name: Production
  description: Production flags
flags:
  - key: checkout
    enabled: true
    metadata:
      owner:
        team: payments
        contacts:
          - name: Ada
            primary: true
          - name: Lin
            primary: false
      regions:
        - us
        - eu
    variants:
      - key: on
        attachment:
          rules:
            - region: us
              weights:
                fast: 2
`,
		},
		{
			name:     "JSON",
			encoding: EncodingJSON,
			input:    `{"namespace":{"key":"production","name":"Production","description":"Production flags"},"flags":[{"key":"checkout","enabled":true,"metadata":{"owner":{"team":"payments","contacts":[{"name":"Ada","primary":true},{"name":"Lin","primary":false}]},"regions":["us","eu"]},"variants":[{"key":"on","attachment":{"rules":[{"region":"us","weights":{"fast":2}}]}}]}]}`,
		},
	}

	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			creator := &mockCreator{getNSErr: status.Error(codes.NotFound, "namespace not found")}
			err := NewImporter(creator).Import(context.Background(), tc.encoding, strings.NewReader(tc.input), false)
			require.NoError(t, err)

			require.Len(t, creator.getNSReqs, 1)
			assert.Equal(t, "production", creator.getNSReqs[0].Key)
			require.Len(t, creator.createNSReqs, 1)
			assert.Equal(t, &flipt.CreateNamespaceRequest{
				Key:         "production",
				Name:        "Production",
				Description: "Production flags",
			}, creator.createNSReqs[0])

			require.Len(t, creator.createflagReqs, 1)
			flag := creator.createflagReqs[0]
			assert.Equal(t, "production", flag.NamespaceKey)
			require.NotNil(t, flag.Metadata)
			assert.Equal(t, map[string]any{
				"owner": map[string]any{
					"team": "payments",
					"contacts": []any{
						map[string]any{"name": "Ada", "primary": true},
						map[string]any{"name": "Lin", "primary": false},
					},
				},
				"regions": []any{"us", "eu"},
			}, flag.Metadata.AsMap())

			require.Len(t, creator.variantReqs, 1)
			assert.Equal(t, "production", creator.variantReqs[0].NamespaceKey)
			assert.JSONEq(t, `{"rules":[{"region":"us","weights":{"fast":2}}]}`, creator.variantReqs[0].Attachment)
		})
	}
}

func TestImport_JSONLeadingComment(t *testing.T) {
	const payload = `{"flags":[{"key":"checkout","enabled":true}]}`
	tests := []struct {
		name    string
		input   string
		wantErr bool
	}{
		{name: "ordinary JSON", input: payload},
		{name: "one leading comment", input: "# exported by Flipt\n" + payload},
